def has_close_elements(numbers: List[float], threshold: float) -> bool:
    if len(numbers) < 2:
        return False
    sorted_nums = sorted(numbers)
    for i in range(1, len(sorted_nums)):
        if sorted_nums[i] - sorted_nums[i - 1] < threshold:
            return True
    return False

def truncate_number(number: float) -> float:
    """
    Return the decimal part of a positive floating point number.
    """
    return number - int(number)

def below_zero(operations: List[int]) -> bool:
    balance = 0
    for op in operations:
        balance += op
        if balance < 0:
            return True
    return False

def max_value_on_paths(N: int, grid_values: list) -> int:
    # Build grid with 1-indexing
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, val in grid_values:
        if x == 0 and y == 0 and val == 0:
            break
        grid[x][y] = val

    # Edge case: single cell
    if N == 1:
        return grid[1][1]

    # Initialize DP arrays
    NEG_INF = -10**9
    dp = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
    dp[1][1] = grid[1][1]

    # Iterate over all possible steps t = i1 + j1 = i2 + j2
    for t in range(2, 2 * N + 1):
        newdp = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
        # i1 and i2 range from max(1, t-N) to min(N, t-1)
        i_min = max(1, t - N)
        i_max = min(N, t - 1)
        for i1 in range(i_min, i_max + 1):
            j1 = t - i1
            if j1 < 1 or j1 > N:
                continue
            for i2 in range(i_min, i_max + 1):
                j2 = t - i2
                if j2 < 1 or j2 > N:
                    continue
                # Compute best previous value
                best = NEG_INF
                # Both came from up
                if i1 > 1 and i2 > 1:
                    best = max(best, dp[i1 - 1][i2 - 1])
                # First from up, second from left
                if i1 > 1 and j2 > 1:
                    best = max(best, dp[i1 - 1][i2])
                # First from left, second from up
                if j1 > 1 and i2 > 1:
                    best = max(best, dp[i1][i2 - 1])
                # Both from left
                if j1 > 1 and j2 > 1:
                    best = max(best, dp[i1][i2])
                if best == NEG_INF:
                    continue
                val = grid[i1][j1]
                if i1 != i2 or j1 != j2:
                    val += grid[i2][j2]
                newdp[i1][i2] = best + val
        dp = newdp

    return dp[N][N] if dp[N][N] != NEG_INF else 0

def calculate_scholarship(grades: List[int], leader: str, west: str, papers: int) -> int:
    avg, class_eval = grades
    scholarship = 0
    if avg > 80 and papers >= 1:
        scholarship += 8000
    if avg > 85 and class_eval > 80:
        scholarship += 4000
    if avg > 90:
        scholarship += 2000
    if avg > 85 and west == 'Y':
        scholarship += 1000
    if class_eval > 80 and leader == 'Y':
        scholarship += 850
    return scholarship

