def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (List[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.
    """
    terms = []
    for idx, coeff in enumerate(coeffs):
        degree = n - idx
        if coeff == 0:
            continue

        # Determine sign
        if not terms:
            sign = '-' if coeff < 0 else ''
        else:
            sign = '-' if coeff < 0 else '+'

        abs_coeff = abs(coeff)

        # Determine coefficient string
        if abs_coeff == 1 and degree > 0:
            coeff_str = ''
        else:
            coeff_str = str(abs_coeff)

        # Determine variable part
        if degree > 1:
            var_str = f'x^{degree}'
        elif degree == 1:
            var_str = 'x'
        else:
            var_str = ''

        terms.append(f'{sign}{coeff_str}{var_str}')

    if not terms:
        return '0'
    return ''.join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original):
        return "Failed"
    mapping = {}
    rev_map = {}
    for e, o in zip(encoded, original):
        if e in mapping:
            if mapping[e] != o:
                return "Failed"
        else:
            mapping[e] = o
        if o in rev_map:
            if rev_map[o] != e:
                return "Failed"
        else:
            rev_map[o] = e
    if len(mapping) != 26 or len(rev_map) != 26:
        return "Failed"
    try:
        return ''.join(mapping[ch] for ch in message)
    except KeyError:
        return "Failed"

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    """
    Perform string transformation from A to B using a set of transformation rules.
    Uses BFS up to 10 steps. Returns minimum steps or "NO ANSWER!" if impossible.
    """
    from collections import deque

    if A == B:
        return 0

    max_steps = 10
    visited = {A}
    queue = deque([(A, 0)])

    while queue:
        current, steps = queue.popleft()
        if steps >= max_steps:
            continue
        for src, tgt in rules:
            start = 0
            while True:
                idx = current.find(src, start)
                if idx == -1:
                    break
                new_str = current[:idx] + tgt + current[idx + len(src):]
                if new_str == B:
                    return steps + 1
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append((new_str, steps + 1))
                start = idx + 1  # allow overlapping matches
    return "NO ANSWER!"

def count_apples_reachable(apple_heights: List[int], tao_reach: int) -> int:
    effective_reach = tao_reach + 30
    count = 0
    for height in apple_heights:
        if height <= effective_reach:
            count += 1
    return count

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    dp = [0] * (m + 1)
    dp[0] = 1
    for limit in a:
        # limit is maximum count for this type
        if limit > m:
            limit = m
        prefix = [0] * (m + 1)
        prefix[0] = dp[0]
        for i in range(1, m + 1):
            prefix[i] = (prefix[i - 1] + dp[i]) % MOD
        newdp = [0] * (m + 1)
        for k in range(m + 1):
            # sum dp[k-t] for t=0..min(limit, k)
            low = k - limit
            if low <= 0:
                newdp[k] = prefix[k]
            else:
                newdp[k] = (prefix[k] - prefix[low - 1]) % MOD
        dp = newdp
    return dp[m] % MOD

def minimum_students_to_leave(heights):
    """
    Calculate the minimum number of students that need to leave to form a choir formation.
    A choir formation is defined such that for some position 'i', the heights of students
    increase from the start to 'i' and decrease from 'i' to the end of the formation.

    Args:
        heights (List[int]): A list of student heights.

    Returns:
        int: The minimum number of students that need to leave.
    """
    n = len(heights)
    if n <= 1:
        return 0

    # Longest increasing subsequence ending at each index
    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and lis[j] + 1 > lis[i]:
                lis[i] = lis[j] + 1

    # Longest decreasing subsequence starting at each index
    lds = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and lds[j] + 1 > lds[i]:
                lds[i] = lds[j] + 1

    # Find maximum bitonic subsequence length
    max_bitonic = 0
    for i in range(n):
        bitonic_len = lis[i] + lds[i] - 1
        if bitonic_len > max_bitonic:
            max_bitonic = bitonic_len

    return n - max_bitonic
